function t(key, vars){
  let s = (I18N[state.lang] && I18N[state.lang][key]) || I18N.en[key] || key;
  if (vars) for (const k in vars) s = s.replaceAll('{'+k+'}', vars[k]);
  return s;
}
function setLang(l){
  state.lang = l; store.set('z2g_lang', l);
  applyI18nStatic();
  if ($('#appShell').classList.contains('on')){ renderSidebar(); renderTopbar(); go(state.view, true); }
}
function applyI18nStatic(){
  $$('[data-i18n]').forEach(el => { el.textContent = t(el.dataset.i18n); });
  $$('.lang-sw button').forEach(b => b.classList.toggle('on', b.dataset.lang === state.lang));
}

