/* ---- 02-api.js ---- */
/* == api == */
/* same-origin backend proxy (Next) or direct browser→GitHub (static monolith) */
const ghBase = () => state.proxy ? '/api/github' : 'https://api.github.com';
async function probeProxy(){
  try {
    const ctl = new AbortController();
    const to = setTimeout(() => ctl.abort(), 1500);
    const r = await fetch('/api/health', { cache:'no-store', signal: ctl.signal });
    clearTimeout(to);
    state.proxy = r.ok;
  } catch(e){ state.proxy = false; }
  return state.proxy;
}
class ApiError extends Error { constructor(status,msg){ super(msg||('HTTP '+status)); this.status=status; } }
async function gh(path, opts={}){
  const headers = { 'Accept':'application/vnd.github+json', 'X-GitHub-Api-Version':'2022-11-28' };
  if (state.token) headers['Authorization'] = 'token ' + state.token;
  if (opts.body) headers['Content-Type'] = 'application/json';
  const res = await fetch(ghBase() + path, { ...opts, headers });
  const sc = res.headers.get('x-oauth-scopes'); if (sc != null) state.scopes = sc;
  const rl = res.headers.get('x-ratelimit-remaining'); if (rl != null) state.rate = +rl;
  updateRateChip && updateRateChip();
  if (!res.ok){
    let msg = res.status + ' ' + res.statusText;
    try { const j = await res.json(); if (j.message) msg = j.message; } catch(e){}
    throw new ApiError(res.status, msg);
  }
  if (res.status === 204) return null;
  const ct = res.headers.get('content-type') || '';
  return ct.includes('json') ? res.json() : res.text();
}
async function ghAll(path){
  const sep = path.includes('?') ? '&' : '?';
  let page = 1, out = [];
  for(;;){ const r = await gh(path + sep + 'per_page=100&page=' + page); out = out.concat(r); if (!Array.isArray(r) || r.length < 100) break; page++; if (page > 20) break; }
  return out;
}
async function fetchRawU8(full, branch, path){
  const res = await fetch(`${ghBase()}/repos/${full}/contents/${encPath(path)}?ref=${encodeURIComponent(branch)}`, {
    headers: { Accept:'application/vnd.github.raw+json', ...(state.token ? { Authorization:'token ' + state.token } : {}) } });
  if (!res.ok) throw new ApiError(res.status, 'Raw fetch failed: ' + path);
  return new Uint8Array(await res.arrayBuffer());
}
const encPath = p => encodeURIComponent(p).replace(/%2F/g,'/');

/* ---- Git Data pipeline ---- */
async function headInfo(full, branch){
  try {
    const ref = await gh(`/repos/${full}/git/ref/heads/${encodeURIComponent(branch)}`);
    const headSha = ref.object.sha;
    const base = await gh(`/repos/${full}/git/commits/${headSha}`);
    return { headSha, baseTree: base.tree.sha };
  } catch(e){
    if (e.status === 404 || e.status === 409) return { headSha: null, baseTree: null }; // empty repo
    throw e;
  }
}
/** entries: [{path, mode, type, sha}] — sha:null deletes the path */
async function commitTree({ full, branch, entries, message, useBase = true, onProgress }){
  const log = m => onProgress && onProgress(m);
  const { headSha, baseTree } = await headInfo(full, branch);
  const treeBody = { tree: entries };
  if (useBase && headSha && baseTree) treeBody.base_tree = baseTree;
  log(t('up_tree'));
  const tree = await gh(`/repos/${full}/git/trees`, { method:'POST', body: JSON.stringify(treeBody) });
  log(t('up_commit'));
  const commit = await gh(`/repos/${full}/git/commits`, { method:'POST', body: JSON.stringify({ message: redact(message), tree: tree.sha, parents: headSha ? [headSha] : [] }) });
  log(t('up_ref'));
  if (!headSha) await gh(`/repos/${full}/git/refs`, { method:'POST', body: JSON.stringify({ ref:'refs/heads/' + branch, sha: commit.sha }) });
  else await gh(`/repos/${full}/git/refs/heads/${encodeURIComponent(branch)}`, { method:'PATCH', body: JSON.stringify({ sha: commit.sha, force:true }) });
  log('✓');
  return commit;
}
async function commitFiles({ full, branch, files, message, mode, onProgress }){
  const log = m => onProgress && onProgress(m);
  const { headSha, baseTree } = await headInfo(full, branch);
  const entries = [];
  const BATCH = 10;
  for (let i = 0; i < files.length; i += BATCH){
    if (state.pushCtl?.cancelled) throw new Error(t('up_cancelled'));
    const batch = files.slice(i, i + BATCH);
    let res;
    for (let attempt = 1; ; attempt++){
      try {
        res = await Promise.all(batch.map(f =>
          gh(`/repos/${full}/git/blobs`, { method:'POST', body: JSON.stringify({ content: b64(f.u8), encoding:'base64' }) })
        ));
        break;
      } catch(e){
        if (attempt >= 2 || state.pushCtl?.cancelled) throw e;
        log('⚠ ' + e.message + ' — retry…');
        await sleep(1500);
      }
    }
    batch.forEach((f, j) => entries.push({ path: f.path, mode:'100644', type:'blob', sha: res[j].sha }));
    log(`${t('up_blobs')}: ${Math.min(i+BATCH, files.length)}/${files.length}`);
  }
  const useBase = mode !== 'replace';
  const treeBody = { tree: entries };
  if (useBase && headSha && baseTree) treeBody.base_tree = baseTree;
  log(t('up_tree'));
  const tree = await gh(`/repos/${full}/git/trees`, { method:'POST', body: JSON.stringify(treeBody) });
  log(t('up_commit'));
  const commit = await gh(`/repos/${full}/git/commits`, { method:'POST', body: JSON.stringify({ message: redact(message), tree: tree.sha, parents: headSha ? [headSha] : [] }) });
  log(t('up_ref'));
  if (!headSha) await gh(`/repos/${full}/git/refs`, { method:'POST', body: JSON.stringify({ ref:'refs/heads/' + branch, sha: commit.sha }) });
  else await gh(`/repos/${full}/git/refs/heads/${encodeURIComponent(branch)}`, { method:'PATCH', body: JSON.stringify({ sha: commit.sha, force:true }) });
  log('✓ ' + t('up_done'));
  return commit;
}
/** rename/move a file keeping its blob (single commit) */
async function renameFileCommit(full, branch, oldPath, newPath, message){
  const meta = await gh(`/repos/${full}/contents/${encPath(oldPath)}?ref=${encodeURIComponent(branch)}`);
  return commitTree({ full, branch, message, entries: [
    { path: newPath, mode:'100644', type:'blob', sha: meta.sha },
    { path: oldPath, mode:'100644', type:'blob', sha: null }
  ]});
}
async function deleteFileCommit(full, branch, path, message){
  const meta = await gh(`/repos/${full}/contents/${encPath(path)}?ref=${encodeURIComponent(branch)}`);
  return commitTree({ full, branch, message, entries: [ { path, mode:'100644', type:'blob', sha: null } ]});
}


/* ---- 03-zip.js ---- */
/* == zip == */
async function inflateRaw(u8){
  if (typeof DecompressionStream === 'undefined') throw new Error('DecompressionStream unsupported — serve over https/localhost');
  const ds = new DecompressionStream('deflate-raw');
  const stream = new Blob([u8]).stream().pipeThrough(ds);
  return new Uint8Array(await new Response(stream).arrayBuffer());
}
async function readZip(buf){
  const bytes = new Uint8Array(buf);
  const dv = new DataView(buf);
  let eocd = -1;
  for (let i = bytes.length - 22; i >= Math.max(0, bytes.length - 65558); i--){
    if (dv.getUint32(i, true) === 0x06054b50){ eocd = i; break; }
  }
  if (eocd < 0) throw new Error('Not a valid .zip archive (EOCD not found)');
  const count = dv.getUint16(eocd + 10, true);
  let off = dv.getUint32(eocd + 16, true);
  const td = new TextDecoder('utf-8');
  const files = [];
  for (let i = 0; i < count; i++){
    if (dv.getUint32(off, true) !== 0x02014b50) break;
    const flags = dv.getUint16(off + 8, true);
    const method = dv.getUint16(off + 10, true);
    const csize = dv.getUint32(off + 20, true);
    const nameLen = dv.getUint16(off + 28, true);
    const extraLen = dv.getUint16(off + 30, true);
    const comLen = dv.getUint16(off + 32, true);
    const lOff = dv.getUint32(off + 42, true);
    const name = td.decode(bytes.subarray(off + 46, off + 46 + nameLen));
    off += 46 + nameLen + extraLen + comLen;
    if (name.endsWith('/') || name.split('/').some(s => s === '.git')) continue;
    if (flags & 1) throw new Error('Archive is encrypted — unpack it first');
    const lnLen = dv.getUint16(lOff + 26, true);
    const leLen = dv.getUint16(lOff + 28, true);
    const dataStart = lOff + 30 + lnLen + leLen;
    const raw = bytes.subarray(dataStart, dataStart + csize);
    let data;
    if (method === 0) data = raw.slice();
    else if (method === 8) data = await inflateRaw(raw);
    else throw new Error('Unsupported compression method: ' + method);
    files.push({ path: name, u8: data, size: data.length });
  }
  return files;
}
function zipCommonRoot(files){
  if (!files.length) return null;
  const root = files[0].path.split('/')[0];
  if (!files.every(f => f.path.split('/')[0] === root)) return null;
  if (!files.every(f => f.path.includes('/'))) return null;
  return root;
}
async function readFolder(dirHandle){
  const files = [];
  const SKIP = new Set(['.git','node_modules','.DS_Store','__pycache__','.venv','dist','build']);
  async function walk(handle, prefix){
    for await (const h of handle.values()){
      if (SKIP.has(h.name)) continue;
      if (h.kind === 'directory') await walk(h, prefix + h.name + '/');
      else {
        const f = await h.getFile();
        const u8 = new Uint8Array(await f.arrayBuffer());
        files.push({ path: prefix + h.name, u8, size: u8.length });
      }
    }
  }
  await walk(dirHandle, '');
  return files;
}


/* ---- 04-scanner.js ---- */
/* == scanner == */
const SENSITIVE_FN = [/^\.env(\..+)?$/i,/credentials\.json$/i,/serviceaccount.*\.json$/i,/id_rsa$/i,/id_ed25519$/i,/\.pem$/i,/\.pfx$/i,/\.p12$/i,/secrets?\.ya?ml$/i,/secrets?\.json$/i];
/* files that can NEVER be included without an explicit per-file acknowledgement */
const NEVER_PUSH = [/^\.env(\.local)?$/i, /^\.env\.production$/i, /\.pem$/i, /id_rsa$/i, /id_ed25519$/i, /credentials\.json$/i, /serviceaccount.*\.json$/i];
const SECRET_PATTERNS = [
  { name:'AWS Access Key ID', re:/AKIA[0-9A-Z]{16}/g },
  { name:'AWS Secret Key', re:/aws(.{0,20})?(secret|access)?[_-]?key['"]?\s*[:=]\s*['"][A-Za-z0-9\/+=]{40}['"]/gi },
  { name:'GitHub Token', re:/gh[pousr]_[A-Za-z0-9]{36,255}/g },
  { name:'GitHub Fine-grained Token', re:/github_pat_[A-Za-z0-9_]{22,255}/g },
  { name:'Slack Token', re:/xox[baprs]-[A-Za-z0-9-]{10,72}/g },
  { name:'Stripe Key', re:/sk_(live|test)_[A-Za-z0-9]{16,64}/g },
  { name:'OpenAI/Anthropic-style Key', re:/sk-[A-Za-z0-9]{20,}/g },
  { name:'Google API Key', re:/AIza[0-9A-Za-z\-_]{35}/g },
  { name:'Private Key Block', re:/-----BEGIN (RSA |EC |OPENSSH |DSA |PGP )?PRIVATE KEY-----/g },
  { name:'Generic API Key/Password', re:/(api[_-]?key|secret|token|password)\s*[:=]\s*['"][A-Za-z0-9_\-\/+=]{16,}['"]/gi },
  { name:'JWT', re:/eyJ[A-Za-z0-9_-]+\.eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/g }
];
const RISKY_PATTERNS = [
  { name:'eval()', re:/\beval\s*\(/g },
  { name:'innerHTML =', re:/\.innerHTML\s*=/g },
  { name:'dangerouslySetInnerHTML', re:/dangerouslySetInnerHTML/g },
  { name:'chmod 777', re:/chmod\s+777/g },
  { name:'document.write', re:/document\.write\s*\(/g },
  { name:'new Function()', re:/new\s+Function\s*\(/g },
  { name:'key in URL', re:/https?:\/\/[^/\s]*[:?][^/\s]*(gh[pousr]_|github_pat_|sk_live_)[A-Za-z0-9_-]+/g }
];
const BIN_EXT = new Set(['png','jpg','jpeg','gif','webp','ico','pdf','zip','tar','gz','7z','woff','woff2','ttf','eot','mp4','mp3','mov','exe','dll','so','dylib','bin','wasm','class','jar']);
function scanFiles(files){
  const td = new TextDecoder('utf-8', { fatal:false });
  const findings = [];
  for (const f of files){
    const base = f.path.split('/').pop();
    const locked = NEVER_PUSH.some(re => re.test(base));
    if (SENSITIVE_FN.some(re => re.test(base))){
      findings.push({ path:f.path, severity:'high', locked, excluded:!isAllowed(f.path),
        matches:[{ line:1, name:'Filename matches secrets-file profile' }] });
      continue;
    }
    const ext = base.includes('.') ? base.split('.').pop().toLowerCase() : '';
    if (BIN_EXT.has(ext) || f.size > 2_000_000) continue;
    let text; try { text = td.decode(f.u8); } catch(e){ continue; }
    if (text.includes('\0')) continue;
    const lines = text.split('\n');
    const matches = [];
    for (const p of SECRET_PATTERNS){
      p.re.lastIndex = 0;
      let m;
      while ((m = p.re.exec(text))){
        const line = text.slice(0, m.index).split('\n').length;
        matches.push({ line, name: p.name, sample: m[0].slice(0, 12) + '…' });
        if (matches.length > 40) break;
      }
    }
    if (!matches.length) continue;
    findings.push({ path:f.path, severity: matches.some(x=>/Private Key|AWS/.test(x.name))?'high':'medium',
      locked, excluded: !isAllowed(f.path), matches, _lines: lines });
  }
  return findings.sort((a,b) => a.severity==='high' ? -1 : 1);
}
/* risky code patterns for the review preview */
function scanRisky(files){
  const td = new TextDecoder('utf-8', { fatal:false });
  const out = [];
  for (const f of files){
    const ext = f.path.split('/').pop().split('.').pop().toLowerCase();
    if (BIN_EXT.has(ext) || f.size > 1_000_000) continue;
    let text; try { text = td.decode(f.u8); } catch(e){ continue; }
    if (text.includes('\0')) continue;
    const hits = [];
    for (const p of RISKY_PATTERNS){
      p.re.lastIndex = 0;
      if (p.re.test(text)) hits.push(p.name);
    }
    if (hits.length) out.push({ path: f.path, hits });
  }
  return out;
}
/* per-repo allowlist (localStorage, not global) */
function allowKey(){ return 'z2g_allow_' + (state.repo ? state.repo.full_name : '_'); }
function isAllowed(path){
  try { const l = JSON.parse(localStorage.getItem(allowKey()) || '[]'); return l.includes(path); } catch(e){ return false; }
}
function allowForRepo(path){
  try {
    const l = JSON.parse(localStorage.getItem(allowKey()) || '[]');
    if (!l.includes(path)) l.push(path);
    localStorage.setItem(allowKey(), JSON.stringify(l));
  } catch(e){}
}
/* mask matched secrets inside file content (replace value with ***) */
function maskFinding(pending, finding){
  const f = pending.files.find(x => x.path === finding.path);
  if (!f || !finding._lines) return false;
  let text = finding._lines.join('\n');
  for (const p of SECRET_PATTERNS){
    p.re.lastIndex = 0;
    text = text.replace(p.re, m => m.slice(0, 4) + '***MASKED***');
  }
  f.u8 = new TextEncoder().encode(text);
  f.size = f.u8.length;
  finding.excluded = false;
  return true;
}
/* generate .env.example content from a .env file */
function envExampleFrom(f){
  const td = new TextDecoder('utf-8', { fatal:false });
  let text; try { text = td.decode(f.u8); } catch(e){ return ''; }
  return text.split('\n').map(line => {
    const m = line.match(/^\s*([A-Za-z_][A-Za-z0-9_.]*)\s*=/);
    if (!m) return line.trim().startsWith('#') ? line : '';
    return m[1] + '=';
  }).filter(l => l !== '').join('\n') + '\n';
}


/* ---- 05-ui.js ---- */
/* == ui == */
function toast(msg, type='ok'){
  const el = document.createElement('div');
  el.className = 'toast ' + type;
  el.innerHTML = icon(type==='ok'?'check':type==='warn'?'warn':'x') + '<div>' + esc(msg) + '</div>';
  $('#toastRoot').appendChild(el);
  setTimeout(() => { el.style.opacity='0'; el.style.transition='opacity .3s'; setTimeout(()=>el.remove(), 320); }, 4200);
}
function fail(e){
  console.error(redact(e.message || e));
  let m = redact(e.message) || 'Error';
  if (e.status === 401) m = t('er_401');
  else if (e.status === 404) m = t('er_404') + (e.message ? ' · ' + redact(e.message) : '');
  else if (e.status === 403 && /secondary rate limit/i.test(m)) m = t('er_secondary');
  else if (e.status === 403) m = t('er_403') + ' · ' + m;
  toast(m, 'bad');
}
function openModal(html, wide=false){
  $('#modalRoot').innerHTML = `<div class="overlay" data-act="overlay-click"><div class="modal${wide?' wide':''}">${html}</div></div>`;
  return $('#modalRoot .modal');
}
function closeModal(){ $('#modalRoot').innerHTML = ''; }
function confirmBox({ title, body, label, danger=false, requireText='' }){
  label = label || (danger ? t('c_delete') : t('c_confirm'));
  return new Promise(resolve => {
    const m = openModal(`
      <div class="m-head"><h3>${esc(title)}</h3><button class="btn btn-ghost btn-icon" data-act="modal-close">${icon('x')}</button></div>
      <div class="m-body"><p class="muted small" style="line-height:1.6">${body}</p>
        ${requireText ? `<label class="lbl" style="margin-top:14px">${t('c_confirm')}: <b class="mono" style="color:var(--text)">${esc(requireText)}</b></label><input class="field" id="cfmInput" autocomplete="off">` : ''}
      </div>
      <div class="m-foot"><button class="btn" data-act="modal-close">${t('c_cancel')}</button>
      <button class="btn ${danger?'btn-danger':'btn-primary'}" id="cfmYes" ${requireText?'disabled':''}>${esc(label)}</button></div>`);
    const inp = m.querySelector('#cfmInput'); const yes = m.querySelector('#cfmYes');
    if (inp) inp.addEventListener('input', () => yes.disabled = inp.value.trim() !== requireText);
    yes.addEventListener('click', () => { closeModal(); resolve(true); });
    m.parentElement.addEventListener('click', ev => {
      if (ev.target === m.parentElement || ev.target.closest('[data-act="modal-close"]')){ closeModal(); resolve(false); }
    });
  });
}
document.addEventListener('keydown', e => { if (e.key === 'Escape') closeModal(); });

/* == charts == */
function eventsByDay(events, days){
  const map = new Map();
  const now = new Date(); now.setHours(0,0,0,0);
  for (const e of events || []){
    const d = new Date(e.created_at); d.setHours(0,0,0,0);
    const k = +d;
    map.set(k, (map.get(k)||0) + (e.type==='PushEvent' ? Math.min(e.payload?.commits?.length||1, 5) : 1));
  }
  const out = [];
  for (let i = days-1; i >= 0; i--){
    const d = new Date(+now - i*86400000);
    out.push({ date: d, count: map.get(+d) || 0 });
  }
  return out;
}
function heatmapHTML(days){
  const data = eventsByDay(state.events, days);
  const max = Math.max(1, ...data.map(d => d.count));
  const lvl = c => c===0?0 : c<=max*0.25?1 : c<=max*0.5?2 : c<=max*0.75?3 : 4;
  // pad to full weeks (Sunday start)
  const first = data[0].date.getDay();
  let cells = '';
  for (let i=0;i<first;i++) cells += '<i style="visibility:hidden"></i>';
  let months = ''; let lastMonth = -1;
  data.forEach(d => {
    if (d.date.getDate() <= 7 && d.date.getMonth() !== lastMonth){
      lastMonth = d.date.getMonth();
      months += `<span style="min-width:${(11+3)*4}px">${d.date.toLocaleDateString(state.lang==='ru'?'ru-RU':'en-US',{month:'short'})}</span>`;
    }
    cells += `<i class="l${lvl(d.count)}" title="${d.count} · ${d.date.toLocaleDateString()}"></i>`;
  });
  return `<div class="hm-wrap"><div class="hm-months">${months}</div><div class="hm">${cells}</div>
    <div class="hm-legend">${t('ov_less')} <i style="background:var(--hm0)"></i><i style="background:var(--hm1)"></i><i style="background:var(--hm2)"></i><i style="background:var(--hm3)"></i><i style="background:var(--hm4)"></i> ${t('ov_more')}</div></div>`;
}
function sparkHTML(series, color='var(--acc)'){
  const w = 220, h = 44, max = Math.max(1, ...series);
  const pts = series.map((v,i) => `${(i/(series.length-1||1))*w},${h-3-(v/max)*(h-8)}`).join(' ');
  const last = series[series.length-1] ?? 0;
  const lx = w, ly = h-3-(last/max)*(h-8);
  return `<svg class="spark" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">
    <polyline points="${pts}" fill="none" stroke="${color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" opacity=".85"/>
    <circle cx="${lx}" cy="${ly}" r="2.6" fill="${color}"/></svg>`;
}


/* ---- 07-monaco.js ---- */
/* == monaco == */
const Monaco = {
  _p: null,
  load(){
    if (this._p) return this._p;
    this._p = new Promise(resolve => {
      if (typeof navigator !== 'undefined' && navigator.onLine === false) return resolve(false);
      const done = v => { this.ready = v; resolve(v); };
      const to = setTimeout(() => done(false), 4500);
      const s = document.createElement('script');
      s.src = 'https://cdnjs.cloudflare.com/ajax/libs/monaco-editor/0.45.0/min/vs/loader.js';
      s.onload = () => {
        try {
          window.require.config({ paths: { vs: 'https://cdnjs.cloudflare.com/ajax/libs/monaco-editor/0.45.0/min/vs' } });
          window.require(['vs/editor/editor.main'], () => { clearTimeout(to); this.setupTheme(); done(true); });
        } catch(e){ clearTimeout(to); done(false); }
      };
      s.onerror = () => { clearTimeout(to); done(false); };
      document.head.appendChild(s);
    });
    return this._p;
  },
  setupTheme(){
    monaco.editor.defineTheme('zg-dark', {
      base: 'vs-dark', inherit: true,
      rules: [
        { token:'comment', foreground:'525d78', fontStyle:'italic' },
        { token:'string', foreground:'7fd6ae' },
        { token:'keyword', foreground:'8fa2ff' },
        { token:'number', foreground:'e8b57e' },
        { token:'type', foreground:'6fc3df' }
      ],
      colors: {
        'editor.background':'#00000000',
        'editor.lineHighlightBackground':'#ffffff08',
        'editorLineNumber.foreground':'#39435c',
        'editorGutter.background':'#00000000',
        'editorIndentGuide.background':'#ffffff12'
      }
    });
  }
};
/* editor pane manager: Monaco when available, highlighted fallback otherwise */
const Editor = {
  inst: null, mode: null, path: null,
  async open(host, { path, text, readOnly }){
    this.path = path; this.host = host;
    const ok = await Monaco.load();
    if (ok){
      host.innerHTML = '<div class="monaco-host"></div>';
      const lang = langByPath(path);
      if (!this.inst){
        this.inst = monaco.editor.create(host.querySelector('.monaco-host'), {
          value: text, language: lang, theme: 'zg-dark', readOnly,
          fontSize: 12.5, lineHeight: 20, minimap: { enabled: false },
          scrollBeyondLastLine: false, automaticLayout: true,
          padding: { top: 10, bottom: 10 }, renderLineHighlight: 'all',
          wordWrap: 'off', scrollbar: { verticalScrollbarSize: 9, horizontalScrollbarSize: 9 }
        });
        this.inst.onDidChangeModelContent(() => onEditorDirty && onEditorDirty(true));
      } else {
        const model = this.inst.getModel();
        monaco.editor.setModelLanguage(model, lang);
        this.inst.setValue(text);
        this.inst.updateOptions({ readOnly });
      }
      this.mode = 'monaco';
    } else {
      this.mode = 'fallback';
      this.fbText = text; this.fbReadOnly = readOnly;
      this.renderFallback();
    }
  },
  renderFallback(){
    const host = this.host;
    if (this.fbReadOnly){
      host.innerHTML = `<div class="ed-fallback"><pre>${hl(esc(this.fbText))}</pre></div>`;
    } else {
      host.innerHTML = `<textarea class="ed-fallback-ta" spellcheck="false" style="position:absolute;inset:0;width:100%;height:100%;background:transparent;border:none;outline:none;color:var(--text);font:12.5px/1.6 var(--mono);padding:12px 14px;resize:none;white-space:pre;overflow:auto">${esc(this.fbText)}</textarea>`;
      host.querySelector('textarea').addEventListener('input', () => onEditorDirty && onEditorDirty(true));
    }
  },
  getValue(){
    if (this.mode === 'monaco' && this.inst) return this.inst.getValue();
    const ta = this.host.querySelector('textarea');
    return ta ? ta.value : this.fbText;
  },
  setReadOnly(ro){
    if (this.mode === 'monaco' && this.inst) this.inst.updateOptions({ readOnly: ro });
    else { this.fbReadOnly = ro; this.renderFallback(); }
  },
  destroy(){ if (this.inst){ this.inst.dispose(); this.inst = null; } }
};
/* lightweight highlighter for fallback mode */
function hl(code){
  return code.replace(/(\/\/[^\n]*|\/\*[\s\S]*?\*\/|#[^\n]*|&quot;[\s\S]*?&quot;|&#39;[\s\S]*?&#39;|`[^`]*`|\b\d+(?:\.\d+)?\b|\b(?:const|let|var|function|return|if|else|for|while|class|import|from|export|default|async|await|try|catch|throw|new|typeof|switch|case|break|continue|def|print|True|False|None|null|undefined|true|false|this|self|in|of|not|and|or|yield|static|public|private|void|int|float|str|bool|package|func|fn|use|mod|match)\b)/g,
  m => {
    if (m.startsWith('//')||m.startsWith('/*')||m.startsWith('#')) return `<span class="tok-c">${m}</span>`;
    if (m.startsWith('&quot;')||m.startsWith('&#39;')||m.startsWith('`')) return `<span class="tok-s">${m}</span>`;
    if (/^\d/.test(m)) return `<span class="tok-n">${m}</span>`;
    return `<span class="tok-k">${m}</span>`;
  });
}


/* ---- 10-views-main.js ---- */
/* == views: main == */
/* ---- Web Crypto at-rest encryption (key = user password, never stored) ---- */
async function deriveKey(pw, salt){
  const km = await crypto.subtle.importKey('raw', new TextEncoder().encode(pw), 'PBKDF2', false, ['deriveKey']);
  return crypto.subtle.deriveKey({ name:'PBKDF2', salt, iterations: 120000, hash:'SHA-256' }, km, { name:'AES-GCM', length:256 }, false, ['encrypt','decrypt']);
}
async function saveEncrypted(token, pw){
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const key = await deriveKey(pw, salt);
  const ct = await crypto.subtle.encrypt({ name:'AES-GCM', iv }, key, new TextEncoder().encode(token));
  store.set('z2g_enc', JSON.stringify({ s:b64(salt), i:b64(iv), c:b64(new Uint8Array(ct)) }));
  state.remembered = true;
}
async function loadEncrypted(pw){
  let d; try { d = JSON.parse(store.get('z2g_enc') || 'null'); } catch(e){ return null; }
  if (!d) return null;
  try {
    const key = await deriveKey(pw, fromB64(d.s));
    const pt = await crypto.subtle.decrypt({ name:'AES-GCM', iv: fromB64(d.i) }, key, fromB64(d.c));
    return new TextDecoder().decode(pt);
  } catch(e){ return null; }
}
function askPassword(unlock=false){
  return new Promise(resolve => {
    const m = openModal(`
      <div class="m-head"><h3>${icon('lock')} ${t('au_pass_t')}</h3><button class="btn btn-ghost btn-icon" data-act="modal-close">${icon('x')}</button></div>
      <div class="m-body">
        ${unlock ? `<input class="field" id="pwA" type="password" placeholder="${t('au_unlock_ph')}">` : `
        <input class="field" id="pwA" type="password" placeholder="${t('au_pass_ph')}">
        <input class="field" id="pwB" type="password" placeholder="${t('au_pass2_ph')}" style="margin-top:10px">`}
        <div class="err" id="pwErr" style="display:none"></div>
      </div>
      <div class="m-foot"><button class="btn" data-act="modal-close">${t('c_cancel')}</button><button class="btn btn-primary" id="pwGo">${icon('check')} OK</button></div>`);
    m.querySelector('#pwGo').addEventListener('click', () => {
      const a = m.querySelector('#pwA').value;
      const bEl = m.querySelector('#pwB');
      if (!unlock && (a.length < 6 || a !== bEl.value)){ const e = m.querySelector('#pwErr'); e.textContent = t('au_pass_err'); e.style.display='block'; return; }
      closeModal(); resolve(a);
    });
    m.parentElement.addEventListener('click', ev => { if (ev.target === m.parentElement || ev.target.closest('[data-act="modal-close"]')){ closeModal(); resolve(null); } });
  });
}
function initAuthBindings(){
  const ti = $('#tokenInput'), cb = $('#connectBtn');
  if (ti) ti.addEventListener('keydown', e => { if (e.key === 'Enter') connect(); });
  if (cb) cb.addEventListener('click', connect);
  const ub = $('#unlockBtn');
  if (ub) ub.addEventListener('click', async () => {
    const pw = $('#unlockPass').value;
    const token = await loadEncrypted(pw);
    if (!token){ const e = $('#unlockErr'); e.textContent = t('au_unlock_err'); e.style.display='block'; return; }
    state.token = token; state.remembered = true;
    try { state.user = await gh('/user'); enterApp(); } catch(err){ state.token=''; fail(err); }
  });
  // scope scenarios
  const SCN = { full:'repo,workflow,user,gist', up:'repo,workflow', read:'' };
  const applyScn = () => {
    const scn = $('#scnModes .mode-card.on')?.dataset.scn || 'full';
    $('#scopeChips').innerHTML = (SCN[scn] ? SCN[scn].split(',') : ['—']).map(s => `<span class="badge b-acc">${s}</span>`).join('');
    $('#tokenLink').href = 'https://github.com/settings/tokens/new?scopes=' + SCN[scn] + '&description=ZipToGit%20Pro';
    $('#tokenLink').style.display = scn === 'read' ? 'none' : '';
  };
  $$('#scnModes .mode-card').forEach(mc => mc.addEventListener('click', () => {
    $$('#scnModes .mode-card').forEach(x => x.classList.remove('on'));
    mc.classList.add('on'); applyScn();
  }));
  applyScn();
  $('#delRepoNote').textContent = t('au_del_note');
}
async function connect(){
  const token = redact($('#tokenInput').value.trim());
  const raw = $('#tokenInput').value.trim();
  const err = $('#authErr'); err.style.display = 'none';
  if (!raw){ err.textContent = '•••'; err.style.display='block'; return; }
  $('#connectBtn').disabled = true;
  try {
    await probeProxy();
    state.token = raw;
    const user = await gh('/user');
    const type = raw.startsWith('github_pat_') ? t('au_fine') : t('au_classic');
    toast(`${user.login} · ${t('au_type')}: ${type} · ${t('au_scopes_found')}: ${state.scopes || '(fine-grained)'}`);
    if ($('#rememberChk').checked){
      if (crypto?.subtle){
        const pw = await askPassword();
        if (pw) await saveEncrypted(raw, pw);
      } else toast('Web Crypto unavailable — token stays in memory only', 'warn');
    }
    state.user = user;
    enterApp(true);
  } catch(e){
    state.token = '';
    err.textContent = redact(e.message);
    err.style.display = 'block';
  }
  $('#tokenInput').value = '';
  $('#connectBtn').disabled = false;
}
function welcomeWizard(){
  if (store.get('z2g_seen')) return;
  store.set('z2g_seen', '1');
  openModal(`
    <div class="m-head"><h3>${icon('home')} ${t('wl_title')}</h3><button class="btn btn-ghost btn-icon" data-act="modal-close">${icon('x')}</button></div>
    <div class="m-body">
      <p class="muted small" style="margin-bottom:12px">${t('wl_s')}</p>
      <div style="display:grid;gap:9px">
        <div class="qa" data-act="nav" data-view="repos"><div class="sic" style="background:rgba(125,140,255,.13);color:#a3adff">${icon('zip')}</div><div><b>${t('ov_qa_zip_t')}</b><span>${t('ov_qa_zip_s')}</span></div></div>
        <div class="qa" data-act="qa-local"><div class="sic" style="background:rgba(76,195,138,.12);color:#4cc38a">${icon('folder')}</div><div><b>${t('ov_qa_dir_t')}</b><span>${t('ov_qa_dir_s')}</span></div></div>
        <div class="qa" data-act="nav" data-view="overview"><div class="sic" style="background:rgba(78,168,222,.12);color:#4ea8de">${icon('home')}</div><div><b>${t('nav_dashboard')}</b><span>heatmap + stats</span></div></div>
      </div>
      <p class="hint" style="margin-top:12px">${t('gh_note')}</p>
    </div>`);
}
function startIdleLogout(){
  const reset = () => {
    clearTimeout(state.idleTimer);
    if (state.remembered) return; // stored (encrypted) token survives idle
    state.idleTimer = setTimeout(() => { toast('Idle logout', 'warn'); location.reload(); }, 30*60*1000);
  };
  ['click','keydown','mousemove'].forEach(ev => document.addEventListener(ev, reset, { passive:true }));
  reset();
}
async function enterApp(first){
  $('#authScreen').style.display = 'none';
  $('#appShell').classList.add('on');
  renderSidebar();
  startIdleLogout();
  try {
    if (!state.user) state.user = await gh('/user');
    $('#userChip').innerHTML = `<img src="${esc(state.user.avatar_url)}" alt=""><div><b>${esc(state.user.login)}</b><span>${esc(state.user.name || state.user.login)}</span></div>`;
    const [repos, events] = await Promise.all([
      ghAll('/user/repos?sort=updated'),
      gh(`/users/${state.user.login}/events/public?per_page=100`).catch(() => [])
    ]);
    state.repos = repos; state.events = events;
    if (first) welcomeWizard();
    // restore UI state (never the token) from sessionStorage
    let ui = null; try { ui = JSON.parse(sessionStorage.getItem('z2g_ui') || 'null'); } catch(e){}
    if (ui && ui.view === 'repo' && ui.repoFull && repos.some(r => r.full_name === ui.repoFull)){
      await openRepo(ui.repoFull);
      if (ui.tab){ state.tab = ui.tab; renderRepo(); }
    } else go(ui && NAV_FLAT.includes(ui.view) ? ui.view : 'overview');
  } catch(e){ fail(e); }
}
const NAV_FLAT = ['overview','repos','gists','activity','settings','repo'];
function logout(){ store.del('z2g_token'); location.reload(); }

/* ---- overview ---- */
